import java.util.*;
public class CF1342E {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        long k = scanner.nextLong();
        final int MD = 998244353;
        if (k >= n) {
            System.out.println(0);
            return;
        }
        int c = n - (int) k;
        long[] ff = new long[n + n];
        long[] gg = new long[n + n];
        long f = 1;
        for (int i = 0; i < n + n; i++) {
            ff[i] = f;
            gg[i] = modInverse(f, MD);
            f = (f * (i + 1)) % MD;
        }
        long ans = 0;
        for (int a = 1; a <= c; a++) {
            long x = (power(a, n, MD) * ch(c, a, ff, gg, MD)) % MD;
            ans += (a % 2 == 0 ? 1 : -1) * x;
        }
        ans = ((ans % MD) + MD) % MD;
        ans = (ans * ch(n, c, ff, gg, MD)) % MD;
        if (k > 0) {
            ans = (ans * 2) % MD;
        }
        System.out.println(ans);
    }

    static long power(long base, int exp, int mod) {
        long result = 1;
        long cur = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * cur) % mod;
            cur = (cur * cur) % mod;
            exp >>= 1;
        }
        return result;
    }

    static long ch(int n, int k, long[] ff, long[] gg, int mod) {
        return (ff[n] * gg[k] % mod) * gg[n - k] % mod;
    }

    static long modInverse(long a, int m) {
        return power(a, m - 2, m);
    }
}
